package org.circus.core;
import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Our input model + machine-verified self-authored UI buffers + actual hidden
 *Windows capture/timers/invalidation. No original game/window procedure runs. */
public final class Pc1InputWindowAudit {
    private static int checks;
    private static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
    public static void main(String[] args)throws Exception{
        if(args.length!=2)throw new IOException("Expected explicit windowDLL/outputdirectory");Path out=Paths.get(args[1]);Files.createDirectories(out);final Pc1InputTests.Owner[] current={null};final int[] changed={0},blocked={0},invalidations={0};List<String> events=new ArrayList<>();
        Pc1WindowsWindow.NativeDispatcher dispatcher=new Pc1WindowsWindow.NativeDispatcher(){public Pc1WindowsWindow.Dispatch dispatch(long hwnd,int message,long wp,long lp)throws IOException{if(message==0x215){changed[0]++;events.add("WM_CAPTURECHANGED:"+lp);if(current[0]!=null)try{current[0].inputRoute.requireBoundary();}catch(IOException expected){blocked[0]++;}}return Pc1WindowsWindow.Dispatch.unhandled();}public int quitFlag(){return 0;}};
        try(final Pc1WindowsWindow window=new Pc1WindowsWindow(Paths.get(args[0]),dispatcher)){
            Pc1UiRaster.InputServices os=new Pc1UiRaster.InputServices(){public void writeVariable(int bank,int index,int value)throws IOException{throw new IOException("This physical leaf audit does not own411B10; raw-variable fixture is separate");}public void setCapture()throws IOException{events.add("SetCapture:"+window.setCapture());}public void releaseCapture()throws IOException{events.add("ReleaseCapture:"+window.releaseCapture());}public int setTimer(int id,int ms)throws IOException{int token=window.setTimer(id,ms);events.add("SetTimer:"+id+":"+ms+":"+token);return token;}public void killTimer(int token)throws IOException{events.add("KillTimer:"+token+":"+window.killTimer(token));}};
            Pc1InputTests.Owner capture=Pc1InputTests.windowFixture("scroll_m0_s0_y24");current[0]=capture;capture.physicalInput=os;capture.compositor.bindInvalidation(r->{invalidations[0]++;if(window.invalidate(r.left,r.top,r.right,r.bottom,false)==0)throw new IOException("Actual InvalidateRect failed");});
            check(window.captureWindow()==0,"No invented initial physical capture");byte[] before=capture.compositor.front().bgr24();capture.inputRoute.timer3(64,24,0);check(window.captureWindow()==window.hwnd()&&capture.ui.readInt(0x9689f8)==5,"Native thumb branch binds actual same mainHWND capture");check(!Arrays.equals(before,capture.compositor.front().bgr24())&&invalidations[0]>0,"Native scrollbar changes same persistent RGB/dirty and actually invalidates");capture.inputRoute.timer3(64,24,0);check(changed[0]==1&&blocked[0]==1,"Repeated SetCapture synchronously dispatches while native input stack is active");capture.inputRoute.input(64,24,1);check(window.captureWindow()==0&&capture.ui.readInt(0x9689f8)==0,"Grid click consumes active thumb with actual ReleaseCapture");check(changed[0]==2&&blocked[0]==2,"ReleaseCapture callback also cannot snapshot the active native input frame");capture.inputRoute.requireBoundary();
            Pc1InputTests.Owner repeat=Pc1InputTests.windowFixture("scroll_m0_s0_y0");current[0]=repeat;repeat.physicalInput=os;repeat.inputRoute.timer3(64,0,0);int token=repeat.ui.readInt(0x94c678);check(token==3&&repeat.ui.readInt(0x9689f8)==1,"Initial scrollbar arrow registers actual timer3 with rawtoken");window.killTimer(token);repeat.ui.writeInt(0x94c678,0);repeat.inputRoute.timer3(0,0,2);check(repeat.ui.readInt(0x94c678)==3,"After caller kills timer, native repeat registers100ms timer3");repeat.raster.stopScroll();check(repeat.ui.readInt(0x94c678)==0,"40B430 kills actual timer then clears canonical token");check(window.windowInfo()[1]==0,"Audit window stays hidden");
            Files.write(out.resolve("capture-front.bgr24"),capture.compositor.front().bgr24());Files.write(out.resolve("events.txt"),events,StandardCharsets.UTF_8);String result="{\"pass\":true,\"checks\":"+checks+",\"actual_hidden_window\":true,\"original_exe_executed\":false,\"capture_changes\":"+changed[0]+",\"native_stack_snapshot_rejections\":"+blocked[0]+",\"actual_invalidations\":"+invalidations[0]+",\"synthetic_buffer_width\":96,\"synthetic_buffer_height\":100,\"pixel_sha256\":\""+Binary.sha256(capture.compositor.front().bgr24())+"\",\"scope\":\"Actual OS capture/timers/invalidate and canonical input/RGB. Not a full game or original screenshot or complete WndProc integration.\"}";Files.write(out.resolve("result.json"),result.getBytes(StandardCharsets.UTF_8));System.out.println("PASS Pc1InputWindowAudit "+checks);
        }
    }
}
